    const fn = new Function(
      'window', 'self', 'document', 'location', 'parent', 'top', 'frames',
      'frameElement', 'globalThis', 'localStorage', 'sessionStorage',
      code + '\n//# sourceURL=' + (url || 'about:blank-frame')
    );
