  for (const p of parts) {
    body += '\n' + (p.code || '') + '\n//# sourceURL=' + (p.url || baseUrl || 'about:blank-frame') + '\n';
    const d = _scanTopLevelDecls(p.code || '');
    for (const n of d.names) names.add(n);
    for (const n of d.funcs) funcs.add(n);
  }
