      for (let i = list.length - 1; i >= lastHideIndex; i--) {
        if (list[i]._popoverShowing && !list[i]._popoverHiding) { _hidePopoverInstance(list[i], fireEvents, undefined, focusPrev); hidAny = true; }
      }
      if (!hidAny) break;
